/* ครัวจานโปรด — Service Worker
   หน้าที่เดียวคือรับ Push Notification (ออเดอร์ใหม่) แล้วเด้งแจ้งเตือนของระบบ
   ให้ได้ แม้ปิดเบราว์เซอร์ไปแล้วหรือล็อกหน้าจออยู่ก็ตาม — ใช้เฉพาะฝั่งแอดมิน
   (ลูกค้าที่สั่งอาหารจะไม่โดนขอสิทธิ์หรือเห็นการแจ้งเตือนพวกนี้เลย เพราะสมัคร
   รับแจ้งเตือนได้จากในหน้าหลังร้านที่ต้องใส่ PIN เท่านั้น) */

const ICON = "data:image/png;base64,";

self.addEventListener("install", () => {
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(self.clients.claim());
});

self.addEventListener("push", (event) => {
  let data = {};
  try { data = event.data ? event.data.json() : {}; } catch (e) {}
  const title = data.title || "🧾 มีออเดอร์ใหม่เข้ามา!";
  const body = data.body || "เปิดดูรายละเอียดที่หลังร้าน";
  event.waitUntil(
    self.registration.showNotification(title, {
      body: body,
      icon: ICON,
      badge: ICON,
      tag: data.code || "kjp-order",
      renotify: true,
      data: { url: "./" },
      vibrate: [200, 100, 200],
    })
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const targetUrl = (event.notification.data && event.notification.data.url) || "./";
  event.waitUntil(
    self.clients.matchAll({ type: "window", includeUncontrolled: true }).then((clientList) => {
      for (const client of clientList) {
        if ("focus" in client) return client.focus();
      }
      if (self.clients.openWindow) return self.clients.openWindow(targetUrl);
    })
  );
});
